  front.forEach(z => { if (['rhoh', 'rincense', 'rtable', 'rmenorah'].indexOf(z.id) >= 0) { z.signNear = 7; z.signY = 2.3; } });
  front.splice(front.indexOf(ap), 1); W.zones.unshift.apply(W.zones, front); W.zones.push(ap);

